package chatbi

import (
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
)

// These routes implement the original page-embedding management screen. The
// application credential is generated by AgentSQL and is never accepted from
// a browser save payload.
func legacyEmbeddedView(app AssistantApplication) map[string]any {
	return map[string]any{
		"id": json.Number(app.ID), "oid": json.Number(app.Workspace),
		"name": app.Name, "description": app.Description, "type": 4,
		"domain": app.Domain, "configuration": app.Configuration,
		"app_id": app.AppID, "app_secret": app.AppSecret,
		"create_time": app.Created.UnixMilli(), "update_time": app.Updated.UnixMilli(),
	}
}

func (h *Handler) legacyEmbeddedList(w http.ResponseWriter, r *http.Request, p Principal, _ string) {
	page, err1 := strconv.Atoi(r.PathValue("page"))
	size, err2 := strconv.Atoi(r.PathValue("size"))
	if err1 != nil || err2 != nil || page < 1 || size < 1 || size > 100 || (page-1) > 1000000/size {
		failure(w, ErrInvalidAssistant)
		return
	}
	items, err := h.service.Assistants(r.Context(), p)
	if err != nil {
		failure(w, err)
		return
	}
	keyword := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("keyword")))
	result := make([]map[string]any, 0)
	for _, app := range items {
		if app.Type == 4 && (keyword == "" || strings.Contains(strings.ToLower(app.Name), keyword)) {
			result = append(result, legacyEmbeddedView(app))
		}
	}
	total := len(result)
	start := (page - 1) * size
	if start >= total {
		result = []map[string]any{}
	} else {
		end := start + size
		if end > total {
			end = total
		}
		result = result[start:end]
	}
	okay(w, map[string]any{"items": result, "total": total})
}

func (h *Handler) legacyEmbeddedRead(w http.ResponseWriter, r *http.Request, p Principal, _ string) {
	app, err := h.service.Assistant(r.Context(), p, ID(r.PathValue("id")))
	if err != nil {
		failure(w, err)
		return
	}
	if app.Type != 4 {
		failure(w, ErrNotFound)
		return
	}
	okay(w, legacyEmbeddedView(app))
}

func (h *Handler) legacyEmbeddedSave(w http.ResponseWriter, r *http.Request, p Principal, _ string) {
	var input legacyAssistantInput
	if !readBody(w, r, &input) {
		return
	}
	if input.Type != 4 || (input.Workspace != nil && *input.Workspace != p.Workspace) {
		failure(w, ErrInvalidAssistant)
		return
	}
	var app AssistantApplication
	if r.Method == http.MethodPut {
		if input.ID == nil {
			failure(w, ErrInvalidAssistant)
			return
		}
		var err error
		app, err = h.service.Assistant(r.Context(), p, *input.ID)
		if err != nil {
			failure(w, err)
			return
		}
		if app.Type != 4 {
			failure(w, ErrInvalidAssistant)
			return
		}
	} else if input.ID != nil {
		failure(w, ErrInvalidAssistant)
		return
	} else {
		app.Enabled = true
	}
	app.Name, app.Description, app.Type, app.Domain, app.Configuration = input.Name, input.Description, 4, input.Domain, input.Configuration
	saved, err := h.service.SaveAssistant(r.Context(), p, app)
	if err != nil {
		failure(w, err)
		return
	}
	okay(w, legacyEmbeddedView(saved))
}

func (h *Handler) legacyEmbeddedDelete(w http.ResponseWriter, r *http.Request, p Principal, _ string) {
	var ids []ID
	if !readBody(w, r, &ids) {
		return
	}
	if len(ids) < 1 || len(ids) > 100 {
		failure(w, ErrInvalidAssistant)
		return
	}
	seen := make(map[ID]bool, len(ids))
	apps := make([]AssistantApplication, 0, len(ids))
	for _, id := range ids {
		if !id.Valid() || seen[id] {
			failure(w, ErrInvalidAssistant)
			return
		}
		seen[id] = true
		app, err := h.service.Assistant(r.Context(), p, id)
		if err != nil {
			failure(w, err)
			return
		}
		if app.Type != 4 {
			failure(w, ErrInvalidAssistant)
			return
		}
		apps = append(apps, app)
	}
	if err := h.service.DeleteEmbeddedBatch(r.Context(), p, apps); err != nil {
		failure(w, err)
		return
	}
	okay(w, nil)
}

func (h *Handler) legacyEmbeddedRotate(w http.ResponseWriter, r *http.Request, p Principal, _ string) {
	app, err := h.service.RotateAssistantSecret(r.Context(), p, ID(r.PathValue("id")))
	if err != nil {
		failure(w, err)
		return
	}
	okay(w, legacyEmbeddedView(app))
}
